scope.inTransaction(
		entityManager -> {
			for ( int i = 0; i < 100_000; i++ ) {
				Person Person = new Person( String.format( "Person %d", i ) );
				entityManager.persist( Person );
			}
		}
);

scope.inTransaction(
		entityManager -> {
			for ( int i = 0; i < entityCount; i++ ) {
				if ( i > 0 && i % batchSize == 0 ) {
					//flush a batch of inserts and release memory
					entityManager.flush();
					entityManager.clear();
				}

				Person Person = new Person( String.format( "Person %d", i ) );
				entityManager.persist( Person );
			}
		}
);

scope.inTransaction(
		entityManager -> {
			ScrollableResults<Person> scrollableResults = null;
			try {
				scrollableResults = entityManager.unwrap( Session.class )
						.createSelectionQuery( "select p from Person p", Person.class )
						.setCacheMode( CacheMode.IGNORE )
						.scroll( ScrollMode.FORWARD_ONLY );

				int count = 0;
				while ( scrollableResults.next() ) {
					Person Person = (Person) scrollableResults.get();
					processPerson( Person );
					if ( ++count % batchSize == 0 ) {
						//flush a batch of updates and release memory:
						entityManager.flush();
						entityManager.clear();
					}
				}
			}
			finally {
				if ( scrollableResults != null ) {
					scrollableResults.close();
				}
			}
		}
);

StatelessSession statelessSession = null;
ScrollableResults<?> scrollableResults = null;
try {
	statelessSession = sessionFactory.openStatelessSession();
	statelessSession.beginTransaction();
	scrollableResults =
			statelessSession.createSelectionQuery( "select p from Person p", Person.class )
					.scroll( ScrollMode.FORWARD_ONLY );

	while ( scrollableResults.next() ) {
		Person Person = (Person) scrollableResults.get();
		processPerson( Person );
		statelessSession.update( Person );
	}
	statelessSession.getTransaction().commit();
}
finally {
	try {
		if ( scrollableResults != null ) {
			scrollableResults.close();
		}

		if ( statelessSession != null ) {
			if ( statelessSession.getTransaction().isActive() ) {
				statelessSession.getTransaction().rollback();
			}
		}
	}
	finally {
		if ( statelessSession != null ) {
			statelessSession.close();
		}
	}
}

@Entity(name = "Person")
@Inheritance(strategy = InheritanceType.JOINED)
public static class Person implements Serializable {

	@Id
	private Integer id;

	@Id
	private String companyName;

	private String name;

	private boolean employed;

	//Getters and setters are omitted for brevity

}

@Entity(name = "Doctor")
public static class Doctor extends Person {
}

@Entity(name = "Engineer")
public static class Engineer extends Person {

	private boolean fellow;

	public boolean isFellow() {
		return fellow;
	}

	public void setFellow(boolean fellow) {
		this.fellow = fellow;
	}
}
